    r_min, r_max, c_min, c_max = rows, -1, cols, -1
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                r_min = min(r_min, r)
                r_max = max(r_max, r)
                c_min = min(c_min, c)
                c_max = max(c_max, c)

    if r_min > r_max:
        return grid

    for r in range(r_min, r_max + 1):
        for c in range(c_min, c_max + 1):
            # Check top source (only for top row, or if corner needs left/right)
            if r == r_min:
                val_top = grid[0][c]
                val_left = grid[r][0]
                val_right = grid[r][cols - 1]

                if val_top != bg:
                    grid[r][c] = val_top
                elif val_left != bg and val_right == bg:
                    grid[r][c] = val_left
                elif val_right != bg and val_left == bg:
                    grid[r][c] = val_right
            # Check bottom source (only for bottom row)
            elif r == r_max:
                val_bot = grid[rows - 1][c]
                val_left = grid[r][0]
                val_right = grid[r][cols - 1]

                if val_bot != bg:
                    grid[r][c] = val_bot
                elif val_left != bg and val_right == bg:
                    grid[r][c] = val_left
                elif val_right != bg and val_left == bg:
                    grid[r][c] = val_right
            # Check left/right for middle rows
            else:
                val_left = grid[r][0]
                val_right = grid[r][cols - 1]

                if val_left != bg:
                    grid[r][c_min] = val_left
                if val_right != bg:
                    grid[r][c_max] = val_right

    return grid
